const columnsMapper = {
  sessionhashofuser: 'sessionhashofuser',
  screenName: 'event_screenname',
  userName: 'username',
  userTime: 'timeforuser',
  eventProperty: 'property',
  deviceModal: 'devicemodel',
  location: 'city',
  eventName: 'event_name',
  appVersion: 'appversion',
  utcTime: 'columndate',
  osVersion: 'osversion',
  browserName: 'browsername',
  browserVersion: 'browserversion',
  deviceType: 'devicetype',
  deviceHeight: 'deviceheight',
  deviceWidth: 'devicewidth',
  deviceOs: 'deviceosname',
};

const platformDisplayMapper = {
  1: 'Android',
  2: 'iOS',
  3: 'Desktop',
}

const EventScreenName = memo(({ row }) => {
  const screenRenamedList = useSelector((state) => state.screenRenamedList);

  const { screen } = row.original;
  const isRenamedScreenName =
    typeof screenRenamedList[screen] !== 'undefined' &&
    screenRenamedList[screen];
  const renamedOrOriginalScreen = isRenamedScreenName
    ? screenRenamedList[screen]
    : screen;
  return (
    <ScreenCell className="no-padding" screen={renamedOrOriginalScreen}>
      <span className="screen-line" />
      <div>{renamedOrOriginalScreen}</div>
    </ScreenCell>
  );
});

const UserName = memo(({ row }) => {
  const {
    userProperty: {
      kUXCam_UserIdentity: kUXCamUserIdentity,
      uxcamuserid,
    },
  } = row.original;
  const UserNameVal = useUserName({
        customUserId: kUXCamUserIdentity,
        uxcamuserid,
      });
  const dispatch = useDispatch();
  const { appId } = useSelector((state) => state.urlReducer);
 
  const handleUserClick = useCallback(() => {
    // let sessionId = sessionIdURL ? `1/${sessionIdURL}` : `1`;
    const url = `/app/${appId}/users/list/1/${uxcamuserid}`;
    // sessionId = sessionIdURL ? `&sessionid=${sessionIdURL}` : '';
    const query = `appId=${appId}&type=session&parentType=usersList&uxcamuserid=${uxcamuserid}&userpage=1&sort=true`;
    dispatch(setFilterPageTable('appuser'));
    Router.push(`/integration?${query}`, `${url}`);
  }, [appId,dispatch,uxcamuserid]);
  return (
    <UnderlinedBoldCell onClick={handleUserClick}>
      {UserNameVal}
    </UnderlinedBoldCell>
  );
});

const UserTime = memo(({ row }) => {
  const { deviceLocalDateTime } = row.original;
  let getDateTimeLocal;
  let getDateLocal;
  try {
    getDateLocal = formatDate(deviceLocalDateTime, 'EEEE');
    getDateTimeLocal = formatDate(deviceLocalDateTime, 'hh:mm a');
  } catch (error) {
    rollbar.error('Issue with date formatting', error);
  }
  return (
    <Cell className='title'>
      {getDateLocal}
      <span className="subtitle">{getDateTimeLocal}</span>
    </Cell>
  );
});

const Device = memo(({ row }) => {
  const { platform, deviceModel } = row.original;
  const deviceModelFormatted = deviceModel?.includes('iPhone')
    ? getRenamedDeviceName(deviceModel)
    : deviceModel?.toUpperCase();
  return (
    <HorizontalCell>
      <div className="platform-icon">
        {platform === 1 ? <AndroidOutlined /> : <AppleOutlined />}
      </div>
      <div>{deviceModelFormatted}</div>
    </HorizontalCell>
  );
});

const Location = memo(({ row }) => {
  const { city, country } = row.original;
  return (
    <HorizontalCell>
      <div>
        <CityStyledSpan className='title'>{city}</CityStyledSpan>
        <span className="subtitle">{country}</span>
      </div>
    </HorizontalCell>
  );
});

const UserUTCTime = memo(({ row }) => {
  const { sessionUploadedDateTime } = row.original;
  let getDateTimeLocal;
  let getDateLocal;
  try {
    getDateLocal = formatDate(sessionUploadedDateTime, 'dd.MM.yyyy');
    getDateTimeLocal = formatDate(sessionUploadedDateTime, 'hh:mm:ss a');
  } catch (error) {
    rollbar.error('Issue with date formatting', error);
  }
  return (
    <Cell className='title'>
      {getDateLocal}
      <span className="subtitle">{getDateTimeLocal}</span>
    </Cell>
  );
});

const AppVersion = memo(({ row }) => {
  const { appVersion } = row.original;
  return (
    <Cell>
      <div>{appVersion}</div>
    </Cell>
  );
});

const OSVersion = memo(({ row }) => {
  const { osVersion, platform } = row.original;
  return (
    <Cell>
      <div>
      {platform === 3 ? '' :`${platformDisplayMapper[platform]}`} {osVersion}
      </div>
    </Cell>
  );
});

const EventName = memo(({ row }) => {
  const { eventName, trackedon } = row.original;
  return (
    <HorizontalCell>
      <div data-intercom-target="EventName">
        <StyledSpan className='title'>{eventName}</StyledSpan>
        <span className="subtitle">
          {trackedon && getDifferenceFromNow(trackedon)}
        </span>
      </div>
    </HorizontalCell>
  );
});

const EventProperty = memo(({ row }) => {
  const { property } = row.original;
  const propertyLength = Object.keys(property).length;

  const getPropertyValue = () =>
    Object.entries(property).map((propt) => (
      <div>{`${propt[0]} : ${propt[1]} \n`}</div>
    ));

  return (
    <ItalicCell>
      <Tooltip title={propertyLength ? getPropertyValue(property) : ''}>
        {`${propertyLength} ${
          propertyLength > 1 ? 'properties' : 'property'
        } (...)`}
      </Tooltip>
    </ItalicCell>
  );
});

const EventPlayCell = memo(({ row }) => {
  const { videoElemRef } = useSessionVideoControlls();
  const {
    userSessionRun,
    sessionDuration,
    id,
    video,
    sessionid,
    eventPropertyTime,
    userProperty,
  } = row.original;
  const {
    urlReducer: { appId, eventpage, sessionid: sessionIdURL, parentType },
    appFilter,
  } = useSelector((state) => state);
  const eventSegment = appFilter?.event?.segment;
  const segmentWithDateRange = useMemo(
    () => [...eventSegment, ...[{ ...appFilter.dateSegment }]],
    [appFilter.dateSegment, eventSegment]
  );
  const onItemSetActive = useCallback(
    (autoplay) => {
      if (videoElemRef?.current)
        videoElemRef.current.currentTime = Number(eventPropertyTime);
      const newPageName =
        parentType === 'eventsList' ? 'events' : 'smart-events';
      const newParentType =
        parentType === 'nocodeEventsList' ? 'nocodeEventsList' : 'eventsList';
      const autoPlayPart = autoplay ? '#autoplay' : '';
      let url = `/app/${appId}/${newPageName}/list/${
        eventpage || 1
      }/${sessionid}/${id}/${eventPropertyTime}`;
      const query = `appId=${appId}&parentType=${newParentType}&sessionid=${sessionid}&eventpage=${
        eventpage || 1
      }&eventid=${id}&starttime=${eventPropertyTime}${autoPlayPart}`;

      url = urlSegmentEncoder(url, segmentWithDateRange);
      url = `${url}${autoPlayPart}`;
      Router.push(`/integration?${query}`, url);
    },
    [
      videoElemRef,
      eventPropertyTime,
      appId,
      eventpage,
      sessionid,
      parentType,
      id,
      segmentWithDateRange,
    ]
  );

  const openEventDetailPage = useCallback(() => {
    const newPageName = parentType === 'eventsList' ? 'events' : 'smart-events';
    const newParentType =
      parentType === 'nocodeEventsList' ? 'nocodeEventsList' : 'eventsList';
    let url = `/app/${appId}/${newPageName}/list/${
      eventpage || 1
    }/${sessionid}/${id}/${eventPropertyTime}?`;
    const query = `appId=${appId}&parentType=${newParentType}&sessionid=${sessionid}&eventpage=${
      eventpage || 1
    }&eventid=${id}&starttime=${eventPropertyTime}&#autoplay`;
    url = urlSegmentEncoder(url, segmentWithDateRange);

    url = `${url}#autoplay`;
    Router.push(`/integration?${query}`, `${url}`);
  }, [
    appId,
    eventPropertyTime,
    eventpage,
    id,
    segmentWithDateRange,
    sessionid,
    parentType,
  ]);

  const expanded = Boolean(sessionIdURL) || false;
  const handleClick = useCallback(
    (e) => {
      e.stopPropagation();
      !expanded ? openEventDetailPage() : onItemSetActive(true);
    },
    [expanded, onItemSetActive, openEventDetailPage]
  );
  return (
    <Item role="button" tabIndex="0">
      <ButtonAndTime data-intercom-target="ButtonTime">
        <>
          <button type="button" onClick={handleClick}>
            {video ? <PlayIcon id="play-icon" /> : <NoVideoIcon />}
          </button>
          <span>
            {formatPlayerTime(eventPropertyTime)}/
            {formatPlayerTime(sessionDuration)}
          </span>
        </>
      </ButtonAndTime>
      <UserAndSessions onClick={handleClick}>
        <SessionUnderLineCell className='title' expanded={expanded}>
          {`Session ${userSessionRun}`}
        </SessionUnderLineCell>
        <span className='subtitle'>
          {userProperty?.kUXCam_UserIdentity}
        </span>
      </UserAndSessions>
    </Item>
  );
});

