const TableHeader = memo(({ header }) => {
  const {
    attribute,
    title,
    subTitle,
    isCustomEventProperty,
    isCustomUserProperty,
  } = header;

  if (isCustomEventProperty || isCustomUserProperty) {
    return (
      <EllipseTitle>
        <em>{ stripCustomPropertyAndMapLabel(title) }</em>
      </EllipseTitle>
    );
  }

  return (
    <EllipseTitle>
      {attribute === 'columndate' ? `${title}${subTitle}` : title}
    </EllipseTitle>
  );
});

const CellMapper = {
  [columnsMapper.eventName]: EventName,
  [columnsMapper.sessionhashofuser]: EventPlayCell,
  [columnsMapper.screenName]: EventScreenName,
  [columnsMapper.userName]: UserName,
  [columnsMapper.userTime]: UserTime,
  [columnsMapper.deviceModal]: Device,
  [columnsMapper.location]: Location,
  [columnsMapper.utcTime]: UserUTCTime,
  [columnsMapper.appVersion]: AppVersion,
  [columnsMapper.eventProperty]: EventProperty,
  [columnsMapper.osVersion]: OSVersion,
  [columnsMapper.browserName]: Browser,
  [columnsMapper.browserVersion]: BrowserVersion,
  [columnsMapper.deviceType]: DeviceType,
  [columnsMapper.deviceHeight]: DeviceHeight,
  [columnsMapper.deviceWidth]: DeviceWidth,
  [columnsMapper.deviceOs]: DeviceOs,
};

const CustomPropsCellRender = memo(({ cell, row }) => {
  const {
    column: { id },
  } = cell;
  const { property, userProperty } = row?.original;

  const value = has(userProperty, removeUxCamCustomProperty(id))
    ? userProperty[removeUxCamCustomProperty(id)] || 'N/A'
    : property[removeUxCamCustomProperty(id)] || 'N/A';
  return (
    <Cell>
      <EllipseText>{containsOnlyNumbers(value.toString())}</EllipseText>
    </Cell>
  );
});

const EventList = ({ data, isLoading, setSortedBy, sortedBy }) => {
  const { urlReducer: urlQuery, appFilter } = useSelector((state) => state);
  const { appId: appid } = urlQuery;
  const [cachedHeadersData, setCachedHeadersData] = useState([]);
  const prevPaginationRef = useRef();
  const { pagination, setPagination } = usePagination();
  const columnHelper = createColumnHelper();

  const {
    eventpage,
    sessionid: sessionIdURL,
    eventid: eventId,
    parentType,
  } = urlQuery;

  // expanded refers to when video player is present
  const expanded = Boolean(sessionIdURL);
  const eventSegment = appFilter?.event?.segment;
  const segmentWithDateRange = useMemo(
    () => [...eventSegment, ...[{ ...appFilter.dateSegment }]],
    [appFilter.dateSegment, eventSegment]
  );
  const moveToRef = useRef();
  const { videoElemRef, prevSessionCallbackRef, nextSessionCallbackRef } =
    useSessionVideoControlls();
  const { pageChange } = useSessionTableHelper({ expanded });
  const headers = data?.header;
  const columnsAreInDefaultState = useMemo(
    () =>
      headers?.filter(
        (item) =>
          item.attribute !== 'country' &&
          item.attribute !== 'trackedon' &&
          item.attribute !== 'video' &&
          (parentType === 'nocodeEventsList'
            ? item.attribute !== 'property'
            : true)
      ),
    [headers, parentType]
  );
  const eventPage = React.useMemo(() => Number(eventpage), [eventpage]);

  const newPagination = useMemo(
    () => (data?.pagination ? data?.pagination : prevPaginationRef?.current),
    [data?.pagination]
  );
  const onItemSetActive = useCallback(
    (sessionId, id, eventPropertyTime, autoplay) => {
      const newPageName =
        parentType === 'eventsList' ? 'events' : 'smart-events';
      const newParentType =
        parentType === 'nocodeEventsList' ? 'nocodeEventsList' : 'eventsList';
      if (videoElemRef?.current)
        videoElemRef.current.currentTime = Number(eventPropertyTime);
      const autoPlayPart = autoplay ? '#autoplay' : '';
      let url = `/app/${appid}/${newPageName}/list/${
        eventPage || 1
      }/${sessionId}/${id}/${eventPropertyTime}`;
      const query = `appId=${appid}&parentType=${newParentType}&sessionid=${sessionId}&eventpage=${
        eventPage || 1
      }&eventid=${id}&starttime=${eventPropertyTime}${autoPlayPart}`;

      url = urlSegmentEncoder(url, segmentWithDateRange);
      url = `${url}${autoPlayPart}`;
      Router.push(`/integration?${query}`, url);
    },
    [videoElemRef, appid, eventPage, parentType, segmentWithDateRange]
  );

  const renderRowSubComponent = React.useCallback(
    (row) => (
      <ExpandedRow>
        <td colSpan={30}>
          <div className="expanded-row-content">
            <TableRowExpandedContent appid={appid} row={row} />
          </div>
        </td>
      </ExpandedRow>
    ),
    [appid]
  );

  const navigatePage = useCallback(
    (newPage) => {
      const newPageName =
        parentType === 'eventsList' ? 'events' : 'smart-events';
      const newParentType =
        parentType === 'nocodeEventsList' ? 'nocodeEventsList' : 'eventsList';
      let url = `/app/${appid}/${newPageName}/list/${newPage}/${sessionIdURL}`;
      url = urlSegmentEncoder(url, segmentWithDateRange);
      const query = `appId=${appid}&parentType=${newParentType}&sessionid=${sessionIdURL}&eventpage=${newPage}&starttime=0#autoplay`;
      Router.push(`/integration?${query}`, `${url}#autoplay`);
    },
    [appid, sessionIdURL, segmentWithDateRange, parentType]
  );

  const eventIndex = useMemo(
    () => data?.body?.findIndex(({ id }) => id === eventId),
    [data, eventId]
  );

  const handleNext = useCallback(() => {
    moveToRef.current = undefined;
    if (!data) {
      return;
    }
    if (eventIndex === -1) {
      return;
    }
    const nextIndex = eventIndex + 1;
    const isLast = data?.body?.length === nextIndex;
    if (isLast) {
      moveToRef.current = 'first';
      navigatePage(eventPage + 1);
    } else {
      const { sessionid, id, eventPropertyTime } = data.body[nextIndex];
      onItemSetActive(sessionid, id, eventPropertyTime, true);
    }
  }, [data, eventIndex, navigatePage, eventPage, onItemSetActive]);

  useEffect(() => {
    if (moveToRef.current && data?.body?.length) {
      let displaySession;
      if (moveToRef.current === 'first') {
        displaySession = data.body[0];
      } else {
        displaySession = data.body[data.body.length - 1];
      }
      const { sessionid, id, eventPropertyTime } = displaySession;
      if (displaySession) {
        onItemSetActive(sessionid, id, eventPropertyTime, true);
      }
      moveToRef.current = undefined;
    }
  }, [data]);

  useEffect(() => {
    nextSessionCallbackRef.current = handleNext;
  }, [handleNext]);

  const handlePrev = useCallback(() => {
    moveToRef.current = undefined;
    if (!data) {
      return;
    }
    if (eventIndex === -1) {
      return;
    }
    const prevIndex = eventIndex - 1;
    const prevPage = prevIndex === -1;
    if (prevPage) {
      if (eventPage === 0) {
        return;
      }
      moveToRef.current = 'last';
      // move to prev page
      navigatePage(eventPage - 1);
    } else {
      const { sessionid, id, eventPropertyTime } = data.body[prevIndex];
      onItemSetActive(sessionid, id, eventPropertyTime, true);
    }
  }, [data, eventIndex, eventPage, navigatePage, onItemSetActive]);

  useEffect(() => {
    prevSessionCallbackRef.current = handlePrev;
  }, [handlePrev]);

  useEffect(() => {
    if (newPagination) {
      prevPaginationRef.current = newPagination;
    }
  }, [newPagination]);

  useEffect(() => {
    setPagination({ ...pagination, pageIndex: eventPage || 1 });
  }, [eventPage])

  useEffect(() => {
    if (columnsAreInDefaultState)
      setCachedHeadersData(columnsAreInDefaultState);
  }, [columnsAreInDefaultState]);

  const highlightActiveRow = useCallback(
    (row) => row.id === eventId,
    [eventId]
  );

  const columns = useMemo(
    () =>
      (columnsAreInDefaultState || cachedHeadersData)
        .map((header) => {
          const {
            isVisible,
            attribute,
            titleInfo: tooltipInfo,
            smallEventTable,
            isSortable,
            isCustomEventProperty,
            isCustomUserProperty,
          } = header;
          return isVisible && (sessionIdURL ? smallEventTable : true)
            ? columnHelper.accessor(attribute, {
                header: (
                  <Tooltip placement="top" title={tooltipInfo}>
                    <span style={{ width: '100%' }}>
                      <TableHeader header={header} />
                    </span>
                  </Tooltip>
                ),
                accessor: attribute,
                titleInfo: tooltipInfo,
                cell:
                  isCustomEventProperty || isCustomUserProperty
                    ? CustomPropsCellRender
                    : CellMapper[attribute] || '',
                width:
                  // eslint-disable-next-line no-nested-ternary
                  attribute === 'sessionhashofuser' ? 200 : 120,
                minWidth: attribute === 'sessionhashofuser' ? 150 : 100,
                enableSorting: isSortable,
                isCustomUserProperty,
                isCustomEventProperty,
              })
            : null;
        })
        .filter((el) => el),
    [columnsAreInDefaultState, cachedHeadersData, sessionIdURL]
  );

  const rowsData = useMemo(
    () =>
      data?.body?.map((item) => ({
        ...item,
        highlightActiveRow: (row) => highlightActiveRow(row),
      })),
    [data?.body, eventId]
  );

  return (
    <SessionTableWrapper>
      <StylesProvider>
        <DashboardTable
          data={rowsData}
          columns={columns}
          sorting={sortedBy}
          setSorting={setSortedBy}
          resizeMode="onChange"
          isLoading={isLoading}
          expandedView={expanded}
          pagination={{
            ...pagination,
            totalPagination: data?.pagination?.pages || 1,
          }}
          setPagination={setPagination}
          handleRouteUpdate={pageChange}
          stickyHeaders={expanded ? [] : ['event_name', 'sessionhashofuser']}
          tableHeight={expanded ? 'calc(100vh - 164px)' : '100%'}
          tableWidth="100%"
          emptyText={{ message: 'No events match the current filters.' }}
          enableRowExpansion
          expandedRowComponent={renderRowSubComponent}
        />
      </StylesProvider>
    </SessionTableWrapper>
  );
};

export default memo(EventList);
