/* eslint-disable no-nested-ternary */
import React, { useEffect } from 'react';
import Link from 'next/link'

import { v4 } from 'uuid'
import { Tooltip } from 'antd'
import { map, isObject } from 'lodash'
import styled from 'styled-components';
import { useDispatch, useSelector } from 'react-redux';

import ScreenTooltip from 'components/common/ScreenTooltip'

import { fetchPlanHatApi } from 'redux/actions/common';

import { getRenamedDeviceName, ordinalSuffixOf } from 'Utils/helpers/commonUtils';
import { formatDate, formatPlayerTime, readableTimeFormatter } from 'Utils/DateConversion/dateConversionUtils'
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';
import { useIsAppType } from 'hooks/useIsAppType';
import { keyLabelMap } from 'components/shared/GlobalFilter/components/utils';

const ExpandedWrapper = styled.div`
  display: flex;
  flex-wrap: wrap;
  padding: 0;
  cursor:default;
`

const ExpandedItem = styled.div`
  margin: 0 30px 10px 0;
  ul{
    li{
      padding:3px 0;
      div{
        padding:3px 0;
      }
      .data-title{
        width: auto;
        display: inline-flex;
        font-size: 12px;
        color: #A2A5AE;
      }
      .data-value{
        color: #161E35;
        font-size: 0.8125rem;
      }
      .separator{
        padding:0 10px;
      }
      a{
        &:hover{
          color:#5D97FF;
        }
      }
    }
  }
`
const categoryName = {
  'User/Device': {
    deviceModel: 'Device type',
    osVersion: 'OS version',
    appVersion: 'App version',
    kUXCam_UserIdentity: 'User ID',
    deviceid: 'Install ID',
    uxcamuserid: 'UXCam user id',
    id: 'Event Number',
  },
  Session: {
    city: 'City',
    country: 'Country',
    deviceLocalDateTime: 'Local Time',
    screen: 'Screen',
    sessionid: 'Session ID',
    eventPropertyTime: 'Time In Session',
    sessionDuration: 'Session Duration',
    sessionNumber: 'Session Number',
  },
  'Event Properties': {
    property: '',
  },
  'User Properties': {
    userProperty: '',
  },
}

const webCategoryName = {
  'User/Device': {
    browserName: 'Browser',
    browserVersion: 'Browser Version',
    deviceOsName: 'OS',
    deviceType: 'Device Type',
    osVersion: 'OS version',
    appVersion: 'App version',
    kUXCam_UserIdentity: 'User ID',
    deviceid: 'Install ID',
    uxcamuserid: 'UXCam user id',
    id: 'Event Number',
  },
  Session: {
    city: 'City',
    country: 'Country',
    deviceLocalDateTime: 'Local Time',
    screen: 'Screen',
    sessionid: 'Session ID',
    eventPropertyTime: 'Time In Session',
    sessionDuration: 'Session Duration',
    sessionNumber: 'Session Number',
  },
  'Event Properties': {
    property: '',
  },
  'User Properties': {
    userProperty: '',
  },
}

const DataValue = ({ children }) => (
  <span className="data-value">{children}</span>
);

const DataTitle = ({ children }) => (
  <span className="data-title">{children}</span>
);

const Separator = () => (
  <span className="separator">:</span>
);

const LinkWithTooltip = ({ url, query, value }) => (
  <Link
    href={query ? { pathname: '/integration', query } : null}
    as={query ? url : null}
    legacyBehavior
  >
    <a href="#!" className="data-value" style={{ textDecoration: 'underline' }}>
      <Tooltip title={value || 'N/A'}>
        {value || 'N/A'}
      </Tooltip>
    </a>
  </Link>
);

const ExternalLinkWithTooltip = ({ url, value }) => (
  <a
    target="_blank"
    rel="noreferrer"
    href={url}
    className="data-value"
    style={{ textDecoration: 'underline' }}
  >
    <Tooltip title={value || 'N/A'}>
      {value || 'N/A'}
    </Tooltip>
  </a>
);

const TableRowExpandedContent = ({ row, appid }) => {
    const tableBodyByIndex = row?.original
    let sessionNumber; let originalScreenName
    const { userProperty, sessionid: sessionId} = tableBodyByIndex;
    const { kUXCam_UserIdentity: kUXCamUserIdentity, uxcamuserid: uxcamUserId } = userProperty
    const dispatch = useDispatch();
    const isWebApp = useIsAppType( 'web' );

    const { appFilter: { dateSegment }} = useSelector(state => state);

    useEffect(() => {
      dispatch(fetchPlanHatApi({ action: 'Click on event', info: { description: 'To expand the event data' }}))
    }, [])

    const getMappedUrls = () => ({
      uxcamuserid: urlSegmentEncoder(`/app/${appid}/users/list/1/${uxcamUserId}?`, [dateSegment]),
      kUXCam_UserIdentity: urlSegmentEncoder(`/app/${appid}/users/list/1/${uxcamUserId}?`, [dateSegment]),
      sessionid: urlSegmentEncoder(`/app/${appid}/events/list/1/${tableBodyByIndex['sessionid']}?`, [dateSegment]),
    });

    const getMappedUrlQueries = () => ({
      uxcamuserid: {
        appId: appid,
        parentType: 'usersList',
        uxcamuserid: uxcamUserId,
        sessionpage: 1,
      },
      kUXCam_UserIdentity: {
        appId: appid,
        parentType: 'usersList',
        uxcamuserid: uxcamUserId,
        sessionpage: 1,
      },
      sessionid: {
        appId: appid,
        parentType: 'eventsList',
        sessionid: tableBodyByIndex.sessionid,
        eventpage: 1,
      },
    });

    const renderValue = (id, displayName) => {
      const mappedUrls = getMappedUrls();
      const mappedUrlQueries = getMappedUrlQueries();
      const mappedIdValue = {
        kUXCam_UserIdentity: kUXCamUserIdentity,
        uxcamuserid: uxcamUserId,
        sessionid: sessionId
      };

      if (id === 'screen') {
        originalScreenName = tableBodyByIndex[id]
        return (
          <ScreenTooltip
            originalScreenName={originalScreenName}
            // eslint-disable-next-line react/no-unstable-nested-components
            onRenderScreen={(renderScreen) => <DataValue>{renderScreen}</DataValue>}
          />
        );
      }

      if (id === 'deviceLocalDateTime') {
        return (
          <DataValue>
            {formatDate(tableBodyByIndex[id], 'hh:mm a')} ({formatDate(tableBodyByIndex[id], 'EEEE')})
          </DataValue>
        );
      }

      if (isObject(tableBodyByIndex[id])) {
        return map(tableBodyByIndex[id], (val, key) => (
          <div key={v4()}>
            <DataTitle>{keyLabelMap[key] ?? key  ?? 'non-attached'}</DataTitle>
            <Separator />
            <DataValue>
              {key === 'anrNumber' ? val.toString() : `${val ?? 'non-attached'}`}
            </DataValue>
          </div>
        ));
      }

      if (id === 'sessionDuration') {
        return <DataValue>{readableTimeFormatter(tableBodyByIndex.sessionDuration)}</DataValue>;
      }

      if (id === 'sessionNumber') {
        sessionNumber = tableBodyByIndex.userSessionRun
        return (
          <DataValue>
            {`${ordinalSuffixOf(sessionNumber)} session of user`}
          </DataValue>
        );
      }

      if (id === 'eventPropertyTime') {
        const percentage = ((tableBodyByIndex.eventPropertyTime / tableBodyByIndex.sessionDuration) * 100).toFixed(2);
        return (
          <DataValue>
            {`${formatPlayerTime(tableBodyByIndex[id])} ( ${percentage}% )`}
          </DataValue>
        );
      }

      if (id === 'sessionid') {
        return (
          <LinkWithTooltip
            url={mappedUrls[id]}
            query={mappedUrlQueries[id]}
            value={mappedIdValue[id]}
          />
        );
      }

      if (id === 'uxcamuserid' || id === 'kUXCam_UserIdentity') {
        return (
          <ExternalLinkWithTooltip
            url={mappedUrlQueries[id] ? mappedUrls[id] : null}
            value={mappedIdValue[id]}
          />
        );
      }

      if (id === 'deviceModel') {
        return <DataValue>{getRenamedDeviceName(tableBodyByIndex[id])}</DataValue>;
      }

      return <DataValue>{tableBodyByIndex[id] || 'N/A'}</DataValue>;
    };

    return (
        <ExpandedWrapper>
          {map(isWebApp ? webCategoryName : categoryName, (value, key) => (
              <ExpandedItem key={key}>
                <h3>{key}</h3>
                <ul key={key}>
                  {map(value, (displayName, id) => {
                     if (id === 'screen') {
                       originalScreenName = tableBodyByIndex[id]
                     }
                    
                    return (
                      <li key={id}>
                        {displayName && (
                          <>
                            <DataTitle>{displayName}</DataTitle>
                            <Separator />
                          </>
                        )}
                        {renderValue(id, displayName)}
                      </li>
                    )
                  })}
                </ul>
              </ExpandedItem>
            ))}
        </ExpandedWrapper>

    )
}
export default TableRowExpandedContent
